func pressureProbeEval(b *board.Board) *sfEval {
	e := &sfEval{b: b}
	var counts pieceTypeCounts
	for row := 0; row < 8; row++ {
		for col := 0; col < 8; col++ {
			p := b.GetPiece(location.NewLocation(location.CoordinateType(row), location.CoordinateType(col)))
			if p == nil {
				continue
			}
			c, pt := p.GetColor(), p.GetPieceType()
			a := p.GetAttackableMoves(b)
			counts[c][pt]++
			e.pieceCount[c][pt]++
			sfSetBit(&e.occ[c], row, col)
			e.attackedBy2[c] |= e.attackedByAll[c] & a
			e.attackedByAll[c] |= a
			e.attackedBy[c][pt] |= a
			e.pieces = append(e.pieces, pcGeneric{row, col, c, pt, a})
		}
	}
	e.phase = endgamePhase(counts)
	e.occAll = e.occ[0] | e.occ[1]
	return e
}

func TestKingPressureProbe(t *testing.T) {
	for _, tc := range []struct{ name, fen string }{
		{"before_g5", "r1b1r1k1/3n1ppp/p6q/4p3/N3P1n1/2BB2P1/PP2NPKb/2RQ1R2"},
		{"after_g5", "r1b1r1k1/3n1p1p/p6q/4p1p1/N3P1n1/2BB2P1/PP2NPKb/2RQ1R2"},
		{"after_Rh1", "r1b1r1k1/3n1p1p/p6q/4p1p1/N3P1n1/2BB2P1/PP2NPKb/2RQ3R"},
	} {
		b := boardFromFENPlacement(t, tc.fen)
		e := pressureProbeEval(b)
		danger := e.kingDanger(color.White)
		bk := e.kingDanger(color.Black)
		for i, p := range e.pieces {
			if p.c == color.Black && p.pt == piece.BishopType && p.row == 1 && p.col == 0 {
				e.pieces[i].row = 7
				e.pieces[i].col = 7
			}
		}
		contactOff := e.kingDanger(color.White)
		t.Logf("%s staticBlack=%d phase=%d whiteKing=%+v blackKing=%+v whiteKingWithoutBh2Contact=%+v", tc.name, evaluateStockfishClassicScore(b, color.Black), e.phase, danger, bk, contactOff)
	}
}
